'use strict';
(()=>{
 const db=window.LWU_FOCUSED_TOPICS,slug=document.body.dataset.focusTopic,root=document.getElementById('subjectRoot');if(!db||!root||!db.registry[slug])return;
 const meta=db.registry[slug],bank=db.quizzes[slug],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 document.title=meta.title+' Quiz | LearnWithUs';const label=document.querySelector('#subjectTitle');if(label)label.textContent=meta.icon+' '+meta.title+' Quiz';
 let pos=0,score=0,items=bank.slice(0,10);if(bank.length<10){root.textContent='This quiz is not available.';return}
 const speak=msg=>{if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(msg);u.lang='en-IN';u.rate=.83;window.speechSynthesis.speak(u)};
 function done(){root.innerHTML=`<section class="subject-quiz-panel"><p class="eyebrow">Quiz finished</p><h2>${score} / ${items.length}</h2><p>${score>=8?'Excellent learning!':'Good effort. Review the lesson and try again.'}</p><div id="sharedScoreCard"></div><nav class="focused-actions"><a class="focused-button" href="${slug}-lesson.html">← Review lesson</a><a class="focused-button focused-primary" href="${slug}-quiz.html">Try again →</a></nav></section>`;
 window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:items.length,title:meta.title+' Quiz',subtitle:'LearnWithUs '+meta.group+' skills',filename:'learnwithus-'+slug+'-score.svg',url:slug+'-quiz.html'});
 window.LearnWithUs?.recordQuiz?.(meta.title+' Quiz',score,items.length,slug+'-quiz.html');}
 function round(){if(pos>=items.length)return done();const q=items[pos];root.innerHTML=`<section class="subject-quiz-panel"><p class="subject-progress">Question ${pos+1} of ${items.length}</p><h2>${esc(q.q)}</h2><div class="focused-choices">${q.o.map(o=>`<button class="focused-choice" type="button" data-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div><p class="focused-feedback" role="status" aria-live="polite"></p><button class="focused-next focused-primary" type="button" id="nextFocusedQuiz" hidden>${pos===items.length-1?'View score →':'Next →'}</button></section>`;let answered=false;const choices=[...root.querySelectorAll('[data-answer]')],msg=root.querySelector('.focused-feedback'),next=root.querySelector('#nextFocusedQuiz');choices.forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const good=b.dataset.answer===q.a;if(good)score++;choices.forEach(x=>{x.disabled=true;if(x.dataset.answer===q.a)x.classList.add('correct')});if(!good)b.classList.add('wrong');const text=good?'Correct answer! It is '+q.a+'.':'Wrong answer. The correct answer is '+q.a+'.';msg.textContent=text+' '+q.explanation;speak(text);window.LWUSmart?.recordAnswer?.(q.q,b.dataset.answer,q.a,{title:meta.title+' Quiz',url:slug+'-quiz.html',category:meta.group,explanation:q.explanation});next.hidden=false;});next.onclick=()=>{pos++;round()}}
 round();
})();
